content:
{
  "findings": [
    {
      "title": "Inclusion criterion 4c requires progression in a previously radiated lesion, but exclusion criterion 2 prohibits radiation within 2 weeks before first dose, and no prior radiation requirement is stated; also contradicts standard RECIST target lesion selection.",
      "page": 38,
      "quote": "c. Documented disease progression in any lesion that was previously radiated in order to serve as a target lesion.",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 3b requires PD within 12 weeks of last PD-1 dose, but exclusion criterion 5 excludes patients with history of immune-related AE requiring permanent discontinuation of PD-1 blockade, which may conflict with the definition of refractory.",
      "page": 38,
      "quote": "b. Have PD (according to RECIST v1.1) within 12 weeks of the last dose of a PD-1 blocking antibody, either as monotherapy or in combination with other agents.",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 7a requires WBC ≥ 2000/mm3, but bone marrow function typically requires higher WBC; also inconsistent with standard hematologic criteria.",
      "page": 39,
      "quote": "− white blood cells ≥ 2000/mm3",
      "severity": "minor"
    },
    {
      "title": "Inclusion criterion 11 requires negative serum pregnancy test before dosing, but Section 4.3 allows serum or urine test within 24 hours; inconsistency in test type and timing.",
      "page": 39,
      "quote": "Women of childbearing potential must have negative serum pregnancy test before dosing at W1D1",
      "severity": "major"
    },
    {
      "title": "Exclusion criterion 4 allows corticosteroids ≤10 mg/day, but Section 4.4 prohibits >10 mg/day at enrollment; however, Section 4.4 also allows corticosteroids for adrenal insufficiency, creating potential conflict with exclusion criterion 4.",
      "page": 39,
      "quote": "Received systemic pharmacologic doses of corticosteroids > 10 mg/day prednisone within 30 days before first dose of study treatment on W1D1.",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 6 requires recovery to Grade 1 or less, but allows persistent AEs like hypothyroidism, which may be Grade 2 or higher; inconsistency.",
      "page": 40,
      "quote": "Not fully recovered from AEs (to Grade 1 or less [per CTCAE v5.0], with the exception of persistent adverse events or sequelae, eg, vitiligo, alopecia, hypothyroidism, diabetes mellitus, and adrenal and/or pituitary insufficiency) due to prior treatment.",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 8 includes 'pericarditis within the previous 6 months' but also 'severe uncontrolled cardiac disease within 6 months' – redundant and potentially contradictory.",
      "page": 40,
      "quote": "severe uncontrolled cardiac disease within 6 months of Screening, including but not limited to poorly controlled hypertension, unstable angina, myocardial infarction, congestive heart failure (New York Heart Association Class II or greater), pericarditis within the previous 6 months, cerebrovascular accident, or implanted or continuous use of a pacemaker or defibrillator.",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 10 allows 'adjuvant hormonal therapy for breast cancer > 3 years from curative-intent surgical resection' but also excludes 'active treatment within the past 3 years' – hormonal therapy may be ongoing, creating contradiction.",
      "page": 40,
      "quote": "Exceptions include cancers that have undergone potentially curative therapy, eg, basal cell carcinoma of the skin, squamous cell carcinoma of the skin, localized prostate cancer with prostate-specific antigen level below 4.0 ng/mL, in situ cervical cancer on biopsy or a squamous intraepithelial lesion on Papanicolaou smear, and thyroid cancer (except anaplastic), in situ breast cancer, and adjuvant hormonal therapy for breast cancer > 3 years from curative-intent surgical resection.",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 18 prohibits blood products or colony stimulating factors within 30 days before start of Screening, but Screening may occur before first dose; timing unclear and may be overly restrictive.",
      "page": 41,
      "quote": "Received blood products (including platelets or red blood cells) or colony stimulating factors (including granulocyte colony stimulating factor, granulocyte/macrophage colony stimulating factor, or recombinant erythropoietin) within 30 days before the start of Screening.",
      "severity": "minor"
    },
    {
      "title": "Section 4.3.1 requires FSH >40 mIU/mL on 2 measurements 2 months apart for females with <12 months amenorrhea, but this is not standard and may be impractical; also inconsistent with typical post-menopausal definition.",
      "page": 41,
      "quote": "Females with less than 12 months of amenorrhea must have a serum follicle stimulating hormone (FSH) level > 40 mIU/mL on 2 measurements performed 2 months apart",
      "severity": "minor"
    },
    {
      "title": "Section 4.4 prohibits 'any live / attenuated vaccine' during treatment and until 100 days post last dose, but Section 4.4.1 allows vaccination with viral vector or mRNA vaccine within 1 week of CMP-001 injection – contradiction.",
      "page": 42,
      "quote": "Any live / attenuated vaccine (eg, varicella, zoster, yellow fever, rotavirus, oral polio and measles, mumps, rubella [MMR]) during treatment and until 100 days post last dose.",
      "severity": "major"
    },
    {
      "title": "Section 4.5 states treatment discontinuation if '2 years of study treatment' but also allows discontinuation for CR after at least 48 weeks and 3 doses beyond CR – inconsistent with maximum 2-year treatment.",
      "page": 43,
      "quote": "• 2 years of study treatment",
      "severity": "minor"
    }
  ]
}
